function Clock() {
  const [tick, setTick] = useState(0);

  useEffect(() => {
    console.log('effect');
  }, []);

  useEffect(() => {
    const id = setTimeout(() => setTick(t => t + 1), 1000);
    return () => clearTimeout(id);
  }, [tick]);

  return <span>{tick}</span>;
}

